components.css:
.ds-email { font-family: var(--font-reading); color: var(--color-ink-primary); } .ds-email-row {
  display: flex;
  gap: calc(var(--space-interface) / 2);
  min-block-size: var(--touch-target);
  align-items: center;
}

.ds-email-row > span {
  min-inline-size: 0;
}

.ds-copy {
  flex: 0 0 var(--touch-target);
  inline-size: var(--touch-target);
  min-block-size: var(--touch-target);
  padding: var(--space-interface);
  border: 0;
  border-radius: 0;
  background: transparent;
  color: var(--color-action);
  font: inherit;
  cursor: pointer;
}

.ds-copy:not([hidden]) {
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.ds-copy svg {
  fill: currentcolor;
}

@media (hover: hover) {
  .ds-copy:hover {
    color: var(--color-action-active);
  }
}

.ds-copy:active {
  color: var(--color-action-active);
}

.ds-copy:disabled {
  color: var(--color-ink-secondary);
  cursor: wait;
}

@media (forced-colors: active) {
  .ds-copy {
    color: ButtonText;
  }
}

.ds-email-actions .ds-gmail {
  padding: var(--space-interface) var(--space-component);
  border: var(--border-width-default) solid currentcolor;
  background: var(--color-surface-raised);
}

.ds-status {
  min-block-size: 1.55em;
  margin-block-start: var(--space-interface);
  color: var(--color-ink-secondary);
}

 .ds-copy:focus-visible { outline: .1875rem solid var(--color-focus); outline-offset: var(--border-width-default); }
